    "Mixed-model እኩልታዎች፡ [XᵀX, XᵀZ; ZᵀX, ZᵀZ + A⁻¹λ] ከλ = σ²e/σ²a ጋር።",
    "ከእውነተኛ breeding values ጋር correlationን አወዳድር፡ የራስ መዝገብ vs BLUP።",
